_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"


def _row_index(seat_number):
    letters = "".join(ch for ch in seat_number if ch.isalpha()).upper()
    index = 0
    for ch in letters:
        index = index * 26 + (ord(ch) - 64)
    return index - 1


